#!/usr/bin/env node
/**
 * routes-against-gateway.mjs — the three-way route parity gate.
 *
 * WHAT IT PROVES
 * --------------
 * That THREE route tables agree:
 *
 *   1. `routing/routes.yaml` — the shared manifest, generated by
 *      `php artisan routes:export`;
 *   2. the Laravel route table — `php artisan route:list --json`;
 *   3. the Go route table — the gateway's `GET /internal/routes`.
 *
 * And not just the route SET: the AUTH classification, the NORMALISED
 * MIDDLEWARE SET, and the RATE LIMIT of every route.
 *
 * WHY IT HAS TO BE A FILE AND NOT A REVIEW
 * ----------------------------------------
 * The rewrite moves 296 API endpoints from Laravel to Go. "Without losing
 * one" is not something a person can check by reading: the tables are four
 * hundred lines long, and the endpoint that goes missing is the one nobody
 * was looking at.
 *
 * A route that exists in Laravel and not in Go is a 404 in production that no
 * test caught, because the test called the Go handler directly.
 *
 * WHY THIS SCRIPT STARTS THE GATEWAY ITSELF
 * ------------------------------------------
 * Because the third table only exists while the gateway is running, and
 * "start it, then run the gate, then stop it" is a sequence that has to
 * work the same way on a developer's machine and in CI. Doing it here means
 * one implementation instead of two, and a failure cannot be a half-run
 * sequence that leaves a process behind.
 *
 * USAGE
 *   node tools/parity/routes-against-gateway.mjs [--port=8080] [--keep]
 *
 * EXIT CODES
 *   0 — the tables agree
 *   1 — they do not
 */

import { spawn, spawnSync } from 'node:child_process';
import { existsSync, mkdirSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

const arg = (name, fallback = null) => {
    const hit = process.argv.find((a) => a.startsWith(`--${name}=`));
    return hit ? hit.slice(name.length + 3) : fallback;
};

const port = Number(arg('port', '8080'));
const keep = process.argv.includes('--keep');
const base = `http://127.0.0.1:${port}`;

// ---------------------------------------------------------------------------
// 1. Build the gateway.
// ---------------------------------------------------------------------------
const binary = join(ROOT, '.tmp', process.platform === 'win32' ? 'gateway.exe' : 'gateway');

mkdirSync(join(ROOT, '.tmp'), { recursive: true });

console.log('three-way route parity');

const build = spawnSync('go', ['build', '-o', binary, './cmd/gateway'], {
    cwd: ROOT,
    encoding: 'utf8',
    env: { ...process.env, GOEXPERIMENT: 'nojsonv2' },
});

if (build.status !== 0) {
    console.error('::error::could not build the gateway.');
    console.error(build.stderr || build.stdout);
    process.exit(1);
}

// ---------------------------------------------------------------------------
// 2. Start it.
// ---------------------------------------------------------------------------
const gateway = spawn(binary, ['--manifest=routing/routes.yaml', `--addr=127.0.0.1:${port}`], {
    cwd: ROOT,
    stdio: ['ignore', 'pipe', 'pipe'],
});

let gatewayLog = '';

gateway.stdout.on('data', (chunk) => { gatewayLog += chunk; });
gateway.stderr.on('data', (chunk) => { gatewayLog += chunk; });

const stop = () => {
    if (!gateway.killed) {
        gateway.kill();
    }
};

process.on('exit', stop);
process.on('SIGINT', () => { stop(); process.exit(130); });
process.on('SIGTERM', () => { stop(); process.exit(143); });

// ---------------------------------------------------------------------------
// 3. Wait for it to answer.
// ---------------------------------------------------------------------------
let ready = false;

for (let attempt = 0; attempt < 40; attempt++) {
    try {
        const response = await fetch(`${base}/healthz`);

        if (response.ok) {
            ready = true;
            break;
        }
    } catch {
        // Not up yet.
    }

    await new Promise((r) => setTimeout(r, 250));
}

if (!ready) {
    console.error('::error::the gateway did not answer /healthz.');
    console.error(gatewayLog);
    stop();
    process.exit(1);
}

// ---------------------------------------------------------------------------
// 4. Compare.
// ---------------------------------------------------------------------------
const gate = spawnSync('node', [join(ROOT, 'tools', 'parity', 'routes.mjs'), `--go=${base}`], {
    cwd: ROOT,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
});

process.stdout.write(gate.stdout ?? '');

if (gate.status !== 0) {
    process.stderr.write(gate.stderr ?? '');
    console.error('');
    console.error('::error::the route tables do not agree. A route that exists in one');
    console.error('::error::and not the other is a 404 in production that no test caught.');
    stop();
    process.exit(1);
}

if (!keep) {
    stop();
}

// The gateway is expected NOT to be ready yet: the gates are declared from
// the manifest and enforced through interfaces that are not implemented
// until the identity and the limiter land. The route table is the thing
// this gate is about, and the readiness probe is a separate signal.
console.log('');
console.log('The manifest, the Laravel route table and the Go route table agree.');
